# Let's try a more efficient approach using SAT encoding
# We'll use PySAT for this

from pysat.solvers import Glucose3
from pysat.card import *
import itertools

n = 12

# Variables: x[i][j] = v is represented by variable (i*n + j)*n + v + 1
# (using 1-based indexing for SAT variables)
def var(i, j, v):
    return (i * n + j) * n + v + 1

clauses = []

# Each cell has exactly one value
for i in range(n):
    for j in range(n):
        # At least one value
        clauses.append([var(i, j, v) for v in range(n)])
        # At most one value (pairwise)
        for v1 in range(n):
            for v2 in range(v1+1, n):
                clauses.append([-var(i, j, v1), -var(i, j, v2)])

# Each row has distinct values (each value appears exactly once)
for i in range(n):
    for v in range(n):
        # Value v appears at least once in row i
        clauses.append([var(i, j, v) for j in range(n)])
        # Value v appears at most once in row i
        for j1 in range(n):
            for j2 in range(j1+1, n):
                clauses.append([-var(i, j1, v), -var(i, j2, v)])

# Each column has distinct values
for j in range(n):
    for v in range(n):
        # Value v appears at least once in column j
        clauses.append([var(i, j, v) for i in range(n)])
        # Value v appears at most once in column j
        for i1 in range(n):
            for i2 in range(i1+1, n):
                clauses.append([-var(i1, j, v), -var(i2, j, v)])

# Idempotent diagonal: x[i][i] = i
for i in range(n):
    clauses.append([var(i, i, i)])

# QG3: x[x[i][j]][x[j][i]] = i
# For each i, j, and for each possible a = x[i][j], b = x[j][i], we need x[a][b] = i
# This is: for all i, j, a, b: (x[i][j]=a AND x[j][i]=b) => x[a][b]=i
# Equivalently: NOT(x[i][j]=a) OR NOT(x[j][i]=b) OR x[a][b]=i
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                clauses.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])

print(f"Number of clauses: {len(clauses)}")
print(f"Number of variables: {n*n*n}")

# Solve
solver = Glucose3()
for c in clauses:
    solver.add_clause(c)

print("Solving...")
if solver.solve():
    model = solver.get_model()
    print("SAT!")

    # Extract solution
    grid = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for v in range(n):
                if var(i, j, v) in model:
                    grid[i][j] = v
                    break

    for row in grid:
        print(row)

    # Verify
    print("\nVerifying...")
    for i in range(n):
        assert len(set(grid[i])) == n
    for j in range(n):
        assert len(set(grid[i][j] for i in range(n))) == n
    for i in range(n):
        assert grid[i][i] == i
    for i in range(n):
        for j in range(n):
            assert grid[grid[i][j]][grid[j][i]] == i

    print("Verified!")
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print(flat)
else:
    print("UNSAT")

solver.delete()
